        value = task["payload"]
        uploaded = self.operator.upload(value.get("upload_id"))
        expected = value.get("expected_revision")
        if isinstance(expected, str) and re.fullmatch(r"\d+", expected):
            expected = int(expected)
        if expected is not None and not _integer(expected):
            raise self.Fault("IMPLEMENTATION_REVISION",
                             "expected_revision must be a nonnegative whole number.")
        selected_id = value.get("plan_id", value.get("id"))
        if selected_id is not None:
            selected_id = self._id(selected_id)
            if not task.get("attempts") or len(task["attempts"]) > 1:
                replay = self._replay(store, selected_id, actor)
                if replay is not None:
                    return self._plan_result(
                        task["workspace"], replay, status="reused",
                        reused_completed_output=True,
                    )
        try:
            result = import_package(
                store, uploaded["path"], expected_revision=expected, actor=actor,
                expected_plan_id=selected_id,
            )
        except RevisionConflict as error:
            if error.conflict_ref:
                error.conflict_download = self._ticket(
                    task["workspace"], error.conflict_ref,
                    "Preserved incoming implementation conflict",
                )
            raise
        extra = {key: item for key, item in result.items() if key not in ("plan", "status")}
        return self._plan_result(task["workspace"], result["plan"], status=result["status"], **extra)

    def _evidence_export(self, store, task, plan_id):
        from model.implementation_evidence import export_package
        # Pin once using the existing immutable per-task report selection mechanism.
        _directory, selected = self._report_selection(store, task, plan_id)
        descriptor = export_package(store, plan_id, revision=selected["revision"])
        plan = store.get(plan_id, selected["revision"])
        download = self._evidence_download(task["workspace"], plan)
        return self._plan_result(
            task["workspace"], plan, status="evidence_exported",
            evidence=descriptor, _downloads=[download],
        )

    def _site_visit_result(self, workspace, value):
        """Reconnect original site/visit source files and the applied revision."""
        result = dict(value)
        plan = validate_plan(result["plan"])
        store = self.store(workspace)
        saved = store.get(plan["id"], plan["revision"])
        if document_digest(saved) != document_digest(plan):
            raise ImplementationError("The original site/visit import revision changed.")
        operation_id = result.get("operation_id")
        if not isinstance(operation_id, str) or not re.fullmatch(r"[a-f0-9]{64}", operation_id):
            raise ImplementationError("The site/visit import needs its original operation identity.")
        history = [row for row in saved.get("field12_site_visit_imports", [])
                   if isinstance(row, dict) and row.get("operation_id") == operation_id]
        if len(history) != 1:
            raise ImplementationError("The original site/visit import history is unavailable.")
        source_ids = [*history[0].get("source_link_ids", []), history[0].get("audit_source_link_id")]
        sources = {row["id"]: row for row in saved["source_links"]}
        attachment_bank = store._directory(saved["id"]) / "attachments"
        operation_bank = store.root / "implementation" / "site-visit-imports" / operation_id
        downloads = [self._snapshot_download(workspace, saved)]
        ticketed = set()
        for source_id in source_ids:
            if not isinstance(source_id, str) or source_id not in sources:
                raise ImplementationError("An original site/visit source link is missing.")
            source = sources[source_id]
            relative = Path(source.get("reference", ""))
            if relative.is_absolute() or ".." in relative.parts:
                raise ImplementationError("The original intake source must remain workspace-relative.")
            path = store.root / relative
            if (source.get("kind") != "local_file" or path.resolve() != path.absolute()
                    or path.parent != attachment_bank):
                raise ImplementationError("The original intake file leaves its plan attachment bank.")
            if str(path) not in ticketed:
                downloads.append(self._ticket(workspace, path, source.get("label") or path.name, source))
                ticketed.add(str(path))
        allowed = {"identity.json", "preview.json", "row-decisions.json", "import.json"}
        for item in result.get("files", []):
            if not isinstance(item, dict) or not isinstance(item.get("path"), str):
                raise ImplementationError("The retained site/visit audit descriptor is invalid.")
            relative = Path(item["path"])
            if relative.is_absolute() or ".." in relative.parts:
                raise ImplementationError("The intake audit must remain workspace-relative.")
            path = store.root / relative
            if path.resolve() != path.absolute():
                raise ImplementationError("The intake audit must not traverse a symlink.")
            if path.parent == operation_bank and path.name in allowed:
                pass
            elif path.parent == attachment_bank and str(path) in ticketed:
                continue
            else:
                raise ImplementationError("The intake audit leaves its original operation.")
            if str(path) not in ticketed:
                downloads.append(self._ticket(workspace, path, item.get("name") or path.name, item))
                ticketed.add(str(path))
        receipt = operation_bank / "import.json"
        if (result.get("receipt_path") != receipt.relative_to(store.root).as_posix()
                or receipt.resolve() != receipt.absolute()):
            raise ImplementationError("The original intake receipt leaves its operation.")
        if str(receipt) not in ticketed:
            with receipt.open("rb") as handle:
                retained = load_json(handle.read(MAX_JSON_BYTES + 1))
            keys = ("schema", "edition", "operation_id", "plan_id", "base_revision",
                    "applied_revision", "applied_document_digest", "source_link_ids",
                    "audit_source_link_id", "sources", "summary", "files", "receipt_path")
            if not isinstance(retained, dict) or any(
                    not _same_json(retained.get(key), result.get(key)) for key in keys):
                raise ImplementationError("The original intake receipt differs from its completed operation.")
            downloads.append(self._ticket(workspace, receipt, "Site/visit import receipt"))
        current = store.get(saved["id"])
        result.update(
            workspace_key=workspace, id=saved["id"], plan_id=saved["id"],
            revision=saved["revision"], applied_revision=saved["revision"],
            current_revision=current["revision"], current_sha256=document_digest(current),
            _downloads=downloads,
        )
        return result

    def _site_visit(self, workspace, value, *, operation, actor=""):
        from model.implementation_site_visit_intake import (
            inspect_site_visit_csv, preview_site_visit_intake, import_site_visit_intake,
        )
        if not isinstance(value, dict):
            raise ImplementationError("Supply the original site/visit CSV selection.")
        if any(key in value for key in ("path", "csv_path", "document", "source_document")):
            raise ImplementationError("Use original upload tickets and a saved native plan revision.")
        ws = self.operator.ws(workspace)
        if operation == "site-visit-inspect":
            kind = value.get("kind")
            if kind not in ("sites", "visits"):
                raise ImplementationError("Choose sites or visits for this original CSV.")
            upload_id = value.get("upload_id")
            if not isinstance(upload_id, str) or not upload_id:
                raise ImplementationError("Upload the original sites or visits CSV.")
            upload = self.operator.upload(upload_id)
            result = inspect_site_visit_csv(
                Path(upload["path"]), filename=upload["filename"],
                delimiter=value.get("delimiter", ","),
                encoding=value.get("encoding", "utf-8-sig"),
            )
            return dict(result, workspace_key=workspace, kind=kind, upload_id=upload_id)
        plan_id = self._id(value.get("id", value.get("plan_id")))
        revision = self._integer(value.get("revision"), "revision")
        document = self.store(workspace).get(plan_id, revision)
        digest = document_digest(document)
        if value.get("document_digest") != digest:
            raise self.Fault("IMPLEMENTATION_SITE_VISIT_BINDING",
                             "Review the exact saved revision before importing sites or visits.", 409)
        selected = value.get("inputs")
        if not isinstance(selected, list) or not 1 <= len(selected) <= 2:
            raise ImplementationError("Select one sites CSV, one visits CSV, or both in the same batch.")
        inputs, kinds = [], set()
        for item in selected:
            if (not isinstance(item, dict) or set(item) - {"kind", "upload_id", "mapping"}
                    or item.get("kind") not in ("sites", "visits")):
                raise ImplementationError("Each input needs its original sites/visits kind, upload and mapping.")
            kind = item["kind"]
            if kind in kinds:
                raise ImplementationError("Each batch can include one original CSV per table.")
            kinds.add(kind)
            upload_id, mapping = item.get("upload_id"), item.get("mapping")
            if not isinstance(upload_id, str) or not upload_id or not isinstance(mapping, dict):
                raise ImplementationError("Upload each original CSV and choose its columns explicitly.")
            upload = self.operator.upload(upload_id)
            inputs.append({"kind": kind, "path": Path(upload["path"]),
                           "filename": upload["filename"], "mapping": mapping})
        if operation == "site-visit-preview":
            result = preview_site_visit_intake(ws, document, inputs)
            return dict(result, workspace_key=workspace, plan_id=plan_id, revision=revision,
                        document_digest=digest)
        if operation != "site-visit-import":
            raise ImplementationError("Choose an original site/visit intake operation.")
        operation_id = value.get("expected_operation_id")
        if not isinstance(operation_id, str) or not re.fullmatch(r"[a-f0-9]{64}", operation_id):
            raise ImplementationError("Preview the original CSV batch before importing it.")
        result = import_site_visit_intake(
            ws, document, inputs, expected_operation_id=operation_id, actor=actor)
        if (not isinstance(result, dict)
                or result.get("schema") != "upstate.implementation-site-visit-import/v1"
                or result.get("operation_id") != operation_id
                or result.get("plan", {}).get("id") != plan_id):
            raise ImplementationError("The site/visit import differs from its reviewed original batch.")
        return self._site_visit_result(workspace, result)

    def _reconciliation_result(self, workspace, value):
        """Expose only verified retained files under the original plan bank."""
        result = dict(value)
        plan = validate_plan(result["plan"])
        plan_id = self._id(result.get("plan_id", plan["id"]))
        if plan_id != plan["id"]:
            raise ImplementationError("The reconciliation receipt identifies another plan.")
        store = self.store(workspace)
        original = store.get(plan_id, plan["revision"])
        if document_digest(original) != document_digest(plan):
            raise ImplementationError("The reconciliation's applied native revision changed.")
        current = store.get(plan_id)
        result.update(workspace_key=workspace, id=plan_id, plan_id=plan_id,
                      revision=plan["revision"], current_revision=current["revision"],
                      current_sha256=document_digest(current))
        downloads = [self._snapshot_download(workspace, plan)]
        operation_id = result.get("operation_id")
        if not isinstance(operation_id, str) or not re.fullmatch(r"[a-f0-9]{64}", operation_id):
            raise ImplementationError("The reconciliation needs its original operation digest.")
        bank = store._directory(plan_id) / "reconciliations" / operation_id
        names = {"resolution.json", "incoming.json", "candidate-plan.json", "applied-plan.json", "receipt.json"}
        for item in result.get("files", []):
            if not isinstance(item, dict) or not isinstance(item.get("path"), str):
                raise ImplementationError("A retained reconciliation file descriptor is invalid.")
            relative = Path(item["path"])
            if relative.is_absolute() or ".." in relative.parts:
                raise ImplementationError("A reconciliation file must remain workspace-relative.")
            path = store.root / relative
            if (path.resolve() != path.absolute() or path.parent != bank
                    or path.name not in names or item.get("name", path.name) != path.name):
                raise ImplementationError("A reconciliation file leaves its original operation audit.")
            downloads.append(self._ticket(workspace, path, path.name, item))
        result["_downloads"] = downloads
        return result

    def _reconciliation(self, workspace, value, *, operation, actor=""):
        from model import implementation_reconciliation as reconciliation

        if not isinstance(value, dict):
            raise ImplementationError("Supply an original returned-plan selection.")
        store = self.store(workspace)
        plan_id = self._id(value.get("id", value.get("plan_id")))
        if operation == "reconciliation-conflicts":
            result = reconciliation.list_conflicts(store, plan_id)
        elif operation == "reconciliation-preview":
            result = reconciliation.preview_reconciliation(
                store, plan_id, value.get("conflict_id"), choices=value.get("choices"))
        elif operation == "reconciliation-apply":
            result = reconciliation.apply_reconciliation(
                store, plan_id, value.get("conflict_id"),
                choices=value.get("choices"),
                expected_operation_id=value.get("expected_operation_id"),
                expected_revision=self._integer(value.get("expected_revision"), "expected_revision"),
                actor=actor,
            )
            return self._reconciliation_result(workspace, result)
        else:
            raise ImplementationError("Choose an original returned-plan review operation.")
        return dict(result, workspace_key=workspace, plan_id=plan_id)

    def invoke(self, task):
        if task["action"] not in ACTIONS:
            raise self.Fault("IMPLEMENTATION_ACTION", "Choose a supported implementation action.")
        workspace = task["workspace"]
        store = self.store(workspace)
        value = task["payload"]
        actor = self._actor(task)
        action = task["action"]
        if action == "implementation.evidence.import":
            return self._evidence_import(store, task, actor)
        if action == "implementation.plan.create":
            document = self._create_document(value, task)
            plan_id = document["id"]
        elif action in ("implementation.plan.import", "implementation.plan.save"):
            document = self._document(value)
            plan_id = document["id"]
        else:
            document = None
            plan_id = self._id(value.get("plan_id", value.get("id")))
        if (action not in ("implementation.plan.report", "implementation.evidence.export", "implementation.observations.import",
                           "implementation.lab.import", "implementation.lab.dispatch",
                           "implementation.lab.dispatch-report", "implementation.briefing.import",
                           "implementation.reconciliation.apply", "implementation.site-visit.import")
                and (not task.get("attempts") or len(task["attempts"]) > 1)):
            replay = self._replay(store, plan_id, actor)
            if replay is not None:
                return self._plan_result(
                    workspace, replay, status="reused", reused_completed_output=True,
                )
        try:
            if action == "implementation.site-visit.import":
                return self._site_visit(workspace, value, operation="site-visit-import", actor=actor)
            if action == "implementation.reconciliation.apply":
                return self._reconciliation(workspace, value, operation="reconciliation-apply", actor=actor)
            if action == "implementation.plan.create":
                return self._plan_result(workspace, store.create(document, actor=actor),
                                         status="created")
            if action == "implementation.plan.import":
                expected = value.get("expected_revision")
                if expected is not None:
                    if isinstance(expected, str) and re.fullmatch(r"\d+", expected):
                        expected = int(expected)
                    if not _integer(expected):
                        raise self.Fault("IMPLEMENTATION_REVISION",
                                         "expected_revision must be a nonnegative whole number.")
                result = store.import_document(document, expected_revision=expected, actor=actor)
                extra = {key: item for key, item in result.items() if key not in ("plan", "status")}
                return self._plan_result(workspace, result["plan"], status=result["status"], **extra)
            if action == "implementation.plan.save":
                expected = self._integer(value.get("expected_revision"), "expected_revision")
                return self._plan_result(workspace, store.save(document, expected, actor=actor))
            if action == "implementation.records.append":
                expected = self._integer(value.get("expected_revision"), "expected_revision")
                saved = store.add_records(
                    plan_id, value.get("collection"), value.get("records"), expected, actor=actor,
                )
                return self._plan_result(workspace, saved, status="appended")
            if action == "implementation.source.attach":
                expected = self._integer(value.get("expected_revision"), "expected_revision")
                return self._attach(store, task, plan_id, expected, actor)
            if action in ("implementation.source.import", "implementation.selection.import"):
                expected = self._integer(value.get("expected_revision"), "expected_revision")
                return self._source_import(store, task, plan_id, expected, actor)
            if action == "implementation.evidence.export":
                return self._evidence_export(store, task, plan_id)
            if action == "implementation.plan.report":
                return self._report(store, task, plan_id)
            if action == "implementation.lab.dispatch-report":
                return self._dispatch_report(workspace, value)
            if action == "implementation.briefing.import":
                return self._briefing(workspace, value, actor=actor)
            if action == "implementation.lab.dispatch":
                return self._dispatch(workspace, value, operation="dispatch", actor=actor)
            if action == "implementation.lab.import":
                return self._lab(workspace, value, operation="lab-import", actor=actor)
            if action == "implementation.observations.import":
                return self._observations(workspace, value)
        except RevisionConflict as error:
            if error.conflict_ref:
                error.conflict_download = self._ticket(
                    workspace, error.conflict_ref, "Preserved incoming implementation conflict",
                )
            raise
        raise self.Fault("IMPLEMENTATION_ACTION", "The implementation action is unavailable.")

    def decorate_task(self, task):
        if task.get("action") not in ACTIONS:
            return task
        workspace = task["workspace"]
        if task.get("state") == "complete":
            result = task.get("result", {})
            if task["action"] == "implementation.site-visit.import":
                refreshed = self._site_visit_result(workspace, result)
                task["result"] = refreshed
                task["_downloads"] = refreshed["_downloads"]
            elif task["action"] == "implementation.reconciliation.apply":
                refreshed = self._reconciliation_result(workspace, result)
                task["result"] = refreshed
                task["_downloads"] = refreshed["_downloads"]
            elif task["action"] == "implementation.lab.dispatch-report":
                refreshed = self._dispatch_report_downloads(workspace, result)
                task["result"] = refreshed
                task["_downloads"] = refreshed["_downloads"]
            elif task["action"] == "implementation.lab.dispatch":
                refreshed = self._dispatch_result(workspace, result["plan_id"], result["dispatch_id"])
                task["result"] = dict(refreshed, status=result.get("status", refreshed["status"]))
                task["_downloads"] = refreshed["_downloads"]
            elif task["action"] == "implementation.plan.report":
                directory = (self.store(workspace).base / self._id(result["plan_id"]) /
                             "reports" / result["report_id"]
                             if result.get("report_id") else Path(result["directory"]))
                refreshed = self._report_result(
                    workspace, directory, expected_plan=result["plan_id"],
                    expected_revision=result["revision"],
                )
                task["_downloads"] = refreshed["_downloads"]
            elif task["action"] == "implementation.evidence.export":
                plan = self.store(workspace).get(result["plan_id"], result["revision"])
                task["_downloads"] = [self._evidence_download(workspace, plan)]
            elif result.get("plan_id") and result.get("revision"):
                plan = self.store(workspace).get(result["plan_id"], result["revision"])
                task["_downloads"] = [self._snapshot_download(workspace, plan)]
        elif task.get("error", {}).get("conflict_ref"):
            path = Path(task["error"]["conflict_ref"])
            plan_id = task["error"].get("plan_id")
            if plan_id:
                expected_directory = (self.store(workspace).base / self._id(plan_id) / "conflicts").resolve()
                if path.resolve().is_relative_to(expected_directory) and path.is_file():
                    task["error"]["conflict_download"] = self._ticket(
                        workspace, path, "Preserved incoming implementation conflict",
                    )
        return task

